import unittest
from candidate import get_positive

class TestGetPositive(unittest.TestCase):
    def test_get_positive_normal_case(self):
        self.assertEqual(get_positive([-1, 2, -4, 5, 6]), [2, 5, 6])

    def test_get_positive_empty_list(self):
        self.assertEqual(get_positive([]), [])

    def test_get_positive_all_positive_numbers(self):
        self.assertEqual(get_positive([5, 3, 2, 3, 9, 123, 1]), [5, 3, 2, 3, 9, 123, 1])

    def test_get_positive_with_zero(self):
        self.assertEqual(get_positive([0, 1, -1]), [1])

    def test_get_positive_all_negative_numbers(self):
        self.assertEqual(get_positive([-1, -2, -3]), [])

    def test_get_positive_none_value_in_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            get_positive([1, None, 3])

    def test_get_positive_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            get_positive(None)

    def test_get_positive_wrong_type_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            get_positive("hello")

    def test_get_positive_boundary_zero_not_included(self):
        self.assertEqual(get_positive([0]), [])

    def test_get_positive_duplicate_positive_values(self):
        self.assertEqual(get_positive([5, 5, -5, 5]), [5, 5, 5])

if __name__ == '__main__':
    unittest.main()
